# 사용법: chmod +x download_pdfs.sh && ./download_pdfs.sh
# 요구사항: wget  (macOS: brew install wget)

OUTDIR="${1:-pdfs}"
mkdir -p "$OUTDIR"
TOTAL=5963
COUNT=0

download() {
  local url="$1" name="$2"
  local dest="$OUTDIR/$name"
  [ -f "$dest" ] && { echo "건너뜀: $name"; return; }
  wget -q -c -O "$dest" "$url" && echo "완료: $name" || echo "오류: $name"
}

